'use strict';

// MODULES //

var isValidBackgroundColor = require( './utils/is-valid-background-color.js' );
var isValidRowCol = require( './utils/is-valid-row-col.js' );

/**
* Method to draw the bar.
*
* @private
* @name setBackgroundColor
* @param {number} row - row number
* @param {number} col - col number
* @param {string} color - color name
* @param {boolean} overwrite - overwrite
* @returns {void}
*/
function setBackgroundColor( row, col, color, overwrite ) {
	var a;
	var b;

	a = ( isValidRowCol( row, col, this._height, this._widht ) && isValidBackgroundColor( color ) );

	// If color is already set to default we can change it
	b = ( overwrite || this._backgroundColorMatrix[ row ][ col ] === this._backgroundColor );
	if ( a && b ) {
		this._backgroundColorMatrix[ row ][ col ] = color;
	}
}

module.exports = setBackgroundColor;
